uniform int u_enabled_1;
uniform vec4 u_color;
uniform float u_width;
uniform int u_wireframe_only;
uniform int u_faces_only;

varying vec3 v_bc;

void draw_wireframe() {
    if (u_enabled_1 != 1) {
        return;
    }

    vec3 d = fwidth(v_bc);  // relative distance to edge
    vec3 fading3 = smoothstep(vec3(0.0), u_width * d, v_bc);
    float opacity = 1.0 - min(min(fading3.x, fading3.y), fading3.z);

    if (u_wireframe_only == 1) {
        if (opacity == 0.0) {
            // Inside a triangle.
            discard;
        }
        // On the edge.
        gl_FragColor = u_color;
        gl_FragColor.a = opacity;
    } else if (u_faces_only == 1) {
        if (opacity == 1.0) {
            // Inside an edge.
            discard;
        }
        // Inside a triangle.
        gl_FragColor.a = 1.0 - opacity;
    } else {
        gl_FragColor = mix(gl_FragColor, u_color, opacity);
    }

}



